                eprint!("{error}");
                code
            })?;
            print!("{output}");
            Ok(())
        }
        CommandId::Check => {
            let options = cli::project::parse_check_options(&args[1..])?;
            let json = options.json;
            let path = match options.input {
                cli::project::CheckInput::Source(path) => path,
                cli::project::CheckInput::Project(manifest_path) => {
