/// Explicit private-host hooks supplied only by the unpublished toolchain.
/// Creates a project and returns the destination as spelled plus the
/// template it published.
pub type NewProjectHook = fn(&[String]) -> Result<(PathBuf, &'static str), (String, u8)>;
/// An embedding host's explicit override for cryptographically verifying
/// bounded offline release material. When absent, the release command uses
/// the pure built-in Sigstore verifier; structural parsing alone is never
/// reported as cryptographic success.
pub type OfflineReleaseVerifier =
    &'static (dyn semaprax::release_provenance::OfflineBundleVerificationCapability + Sync);
/// The unpublished source-live host's explicit bridge for one checked
/// source-Agent handoff. The control adapter supplies its retained supervisor
/// and compiler-derived plan; the host still owns every provider, checkpoint,
/// policy, and journal input in `arguments`.
pub type SourceAgentDevHook = fn(
    &mut project::HotReloadSession,
    project::HotReloadPlan,
    &[String],
) -> Result<(), (String, u8)>;

#[allow(clippy::type_complexity)]
pub struct PrivateHost {
    pub new_project: NewProjectHook,
    pub source_live: fn(&[String]) -> Result<String, (String, u8)>,
    pub source_agent_dev: Option<SourceAgentDevHook>,
    pub native_authority_check: fn(&[String]) -> Result<String, (String, u8)>,
    /// Harness provider host; prints its own stdout/stderr and returns the exit code.
    pub harness: fn(&[String]) -> u8,
    pub build_rust: fn(&mut project::ProjectSnapshot, &Path) -> Result<(), Vec<Diagnostic>>,
    pub offline_release_verifier: Option<OfflineReleaseVerifier>,
    #[cfg(windows)]
    pub build_owned_npm: fn(&mut project::ProjectSnapshot, &Path) -> Result<(), Vec<Diagnostic>>,
}

// Windows reserves a smaller main-thread stack than the admitted compiler
// depth requires. One explicit worker keeps the CLI's stack budget identical
// across targets without changing the library entry points.
const CLI_STACK_BYTES: usize = 16 * 1024 * 1024;

pub fn main_with_host(host: Option<&'static PrivateHost>) -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let recovery_hint = cli::help::usage_recovery_hint(&args, host.is_some());
    let worker = match std::thread::Builder::new()
        .name("semaprax-cli".to_owned())
        .stack_size(CLI_STACK_BYTES)
        .spawn(move || run(args, host))
    {
        Ok(worker) => worker,
        Err(error) => {
            eprintln!("fatal: unable to start the bounded compiler worker: {error}");
            return ExitCode::from(2);
        }
    };
    let outcome = match worker.join() {
        Ok(outcome) => outcome,
        Err(payload) => std::panic::resume_unwind(payload),
    };
    cli::help::finish(outcome, recovery_hint)
}

fn require_private_host<'a>(
    host: Option<&'a PrivateHost>,
    operation: &str,
) -> Result<&'a PrivateHost, u8> {
    host.ok_or_else(|| {
        eprintln!("{operation} is unavailable in the standalone crates.io package; use the unpublished semaprax-full toolchain CLI");
        2
    })
}

fn run(args: Vec<String>, host: Option<&PrivateHost>) -> Result<(), u8> {
    let Some(command) = args.first().map(String::as_str) else {
        print_help(host.is_some());
        return Err(2);
    };
    if let Some(outcome) = cli::help::dispatch(&args, host.is_some()) {
        return outcome;
    }
    if args.len() == 2 && matches!(args[1].as_str(), "--help" | "-h") {
        return print_scoped_help(command, host.is_some());
    }
    if cli::help::requests_help(&args[1..]) {
        eprintln!("help flags are admitted only as the sole operand of a command");
        return Err(2);
    }
    let Some(command_id) = cli::help::parse(command, true) else {
        eprint!("{}", cli::help::unknown_diagnostic(command, host.is_some()));
        print_help(host.is_some());
        return Err(2);
    };
    use cli::help::CommandId;
    match command_id {
        CommandId::Dev => hot_reload::run(&args[1..], host.and_then(|host| host.source_agent_dev)),
        CommandId::SourceLive => {
            let host = require_private_host(host, "source-live")?;
            let output = (host.source_live)(&args[1..]).map_err(|(error, code)| {
                eprintln!("source-live: {error}");
                code
            })?;
            print!("{output}");
            Ok(())
        }
        CommandId::Harness => match (require_private_host(host, "harness")?.harness)(&args[1..]) {
            0 => Ok(()),
            code => Err(code),
        },
        CommandId::NativeAuthorityCheck => {
            let host = require_private_host(host, "native-authority-check")?;
            let output = (host.native_authority_check)(&args[1..]).map_err(|(error, code)| {
                eprint!("{error}");
                code
            })?;
            print!("{output}");
            Ok(())
        }
        CommandId::Check => {
