                |error| {
                    eprintln!("{error}");
                    2
                },
            )?;
            print!("{output}");
            Ok(())
        }
        CommandId::Help => {
            if args.len() == 1 {
                print_help(host.is_some());
                Ok(())
            } else {
                eprintln!("unknown command `{command}`\n");
                print_help(host.is_some());
                Err(2)
            }
        }
    }
}

