mod tests;

pub(crate) fn preflight_owned_for_change(
    path_set_source: &str,
    sources: Vec<SemanticWorkspaceSource>,
    change_builder_limit: usize,
) -> Result<SemanticWorkspacePreflight, WorkspaceReportFailure> {
    preflight_typed(
        path_set_source,
